/* Connected room pickup: organizer assignments and individual reservations. */
'use strict';
const v2Base={render,handle,overlay:renderOverlay,bar:demoBar,bookings:availabilityBookings,rooms:reservationRooms,reservation:adminReservation};
const v2InvoiceBase=adminInvoice;
const v2DocumentBase=documentHTML,v2PdfTextBase=pdfText;
const v2Types=['Standard Single Room','Standard Double Room','Cabin'];
const v2Active=()=>!!state.pickup?.active;
const pickup=()=>state.pickup;
const roomSlots=()=>pickup().slots;
const slotById=id=>roomSlots().find(s=>s.id===id);
const individualById=id=>pickup().reservations.find(r=>r.id===id)||pickup().slots.find(s=>s.guestPortal?.id===id)?.guestPortal;
const slotReservation=s=>pickup().reservations.find(r=>r.slotId===s.id);
const roomRate=type=>state.quote.rooms.find(r=>r.type===type)?.rate||140;
const roomTotal=type=>Math.round(roomRate(type)*nights()*(state.quote.tax?1.1:1)*100)/100;
const pickupCredit=()=>v2Active()?pickup().reservations.filter(r=>r.paid).reduce((n,r)=>n+r.amount,0):0;
const groupInvoiceTotal=()=>Math.round((totals().total-pickupCredit())*100)/100;
const openSlots=type=>roomSlots().filter(s=>!s.guest&&(!type||s.type===type));
const v2Full=g=>[g.first,g.last].filter(Boolean).join(' ');
const v2Guest=(first,last,email)=>({first,last,email,phone:''});
function setupPickup(seed=false){
 const slots=state.quote.rooms.flatMap((r,i)=>Array.from({length:r.qty},(_,j)=>({id:'slot-'+i+'-'+j,type:r.type,unit:i===2?'Cabin '+(j+1):String((i===0?100:200)+j+1),guest:null,payer:null,status:'Open'})));
 state.pickup={active:true,slots,reservations:[],nextId:36,selectedType:'Standard Double Room',codeApplied:false,guestDraft:{},viewAll:false,activities:[],inviteQueue:[]};
 if(!seed)return;
 const place=(type,index,guest,payer,status,resId)=>{const s=slots.filter(s=>s.type===type)[index];if(!s)return;s.guest=guest;s.payer=payer;s.status=status;if(resId)pickup().reservations.push({id:resId,slotId:s.id,guest:{...guest},type:s.type,unit:s.unit,status:status==='Paid'?'Confirmed':'Pending Approval',paid:status==='Paid',amount:roomTotal(type),activities:[],checkedIn:false,checkedOut:false});};
 place(v2Types[0],0,v2Guest('Maya','Thompson','maya.thompson@horizon.example'),'Organizer','Assigned');
 place(v2Types[0],1,v2Guest('Daniel','Okafor','daniel.okafor@horizon.example'),'Organizer','Assigned');
 place(v2Types[0],2,v2Guest('Elena','Rossi','elena.rossi@horizon.example'),'Guest','Invited','00034');
 place(v2Types[1],1,v2Guest('Grace','Liu','grace.liu@horizon.example'),'Guest','Paid','00033');
 place(v2Types[1],2,v2Guest('Omar','Haddad','omar.haddad@horizon.example'),'Organizer','Assigned');
 place(v2Types[2],0,v2Guest('Marcus','Webb','marcus.webb@horizon.example'),'Guest','Invited','00035');
 pickup().inviteQueue=slots.filter(s=>s.guest&&!s.invited&&s.status!=='Paid').map(s=>s.id);
}
function startVideo2Sample(){
 if(!state.video1Snapshot)state.video1Snapshot=JSON.parse(JSON.stringify({...state,video1Snapshot:undefined,pickup:undefined}));
 state.request={...defaults,id:'GBR-008',status:'Converted'};
 state.quote=buildQuote();Object.assign(state.quote,{rooms:[{type:v2Types[0],bed:'Single',qty:12,rate:140,available:12},{type:v2Types[1],bed:'Double',qty:6,rate:140,available:7},{type:v2Types[2],bed:'Double',qty:4,rate:190,available:4}],cateringQty:96,status:'Executed',paid:true,payment:{amount:9306,last4:'4242',reference:'PAY-008',date:'Sep 22, 2026'},signature:{name:'Maya Thompson',date:'Sep 22, 2026'},venueConfirmed:true});
 state.reservation={id:'00031',groupCode:'GBR-008',status:'Confirmed',assigned:true,color:'#fad659',notes:'Confirmed Horizon Foundation group.'};
 setupPickup(true);state.ui.app='guest';state.ui.guest='organizer';state.ui.admin='individual-list';state.ui.video=2;modal=null;availability=null;save();render();window.scrollTo(0,0);
}
function v2Pill(text){return `<span class="v2-pill ${text==='Invited'?'waiting':text==='Open'?'open':''}">${esc(text)}</span>`;}
function v2Page(body,wide=false){return `<div class="guest pickup-guest">${guestHeader()}<div class="pickup-main ${wide?'wide':''}">${body}</div>${guestFooter()}</div>`;}
function v2Title(title,sub,actions=''){return `<div class="pickup-title"><div><h1>${title}</h1><p>${sub}</p></div>${actions?'<div class="row">'+actions+'</div>':''}</div>`;}
function organizerPage(){const p=pickup(),slots=roomSlots(),assigned=slots.filter(s=>s.guest),waiting=assigned.filter(s=>s.status==='Invited'),paidByOrg=assigned.filter(s=>s.payer==='Organizer');
 const preview=[...slots.filter(s=>s.type===v2Types[0]).slice(0,4),...slots.filter(s=>s.type===v2Types[1]).slice(1,4),...slots.filter(s=>s.type===v2Types[2]).slice(0,1)];
 const rows=(p.viewAll?slots:preview).map(s=>[esc(s.type),s.guest?'<div class="pickup-guest-cell"><b>'+esc(v2Full(s.guest))+'</b><small>'+esc(s.guest.email)+'</small></div>':'<span class="muted">Not assigned</span>',s.payer||'—',v2Pill(s.status),button(s.status==='Open'?'Add guest':s.status==='Invited'?'Resend':s.status==='Paid'?'View':'Change','v2-slot-'+s.id,'link')]);
 const cards=[['Rooms in your block',slots.length,requestRoomSummary(state.request)],['Assigned',assigned.length,paidByOrg.length+' paid by you · '+assigned.filter(s=>s.status==='Paid').length+' paid by guest'],['Waiting for guests',waiting.length,'Invitation sent'],['Still open',slots.length-assigned.length,'Add a guest or share the code']];
 return v2Page(v2Title('Assign your rooms',esc(state.request.group)+' · '+dates(),button('Import list','v2-import')+button('Auto-assign','v2-auto')+button('Send invites','v2-invites')+button('Add guest','v2-add','primary'))+'<div class="pickup-summary">'+cards.map(([a,b,c])=>'<section><small>'+a+'</small><strong>'+b+'</strong><small>'+c+'</small></section>').join('')+'</div><div class="organizer-columns"><section class="pickup-table">'+table(['ROOM','GUEST','WHO PAYS','STATUS',''],rows)+'<div class="pickup-table-footer">Showing '+rows.length+' of '+slots.length+' rooms · '+button(p.viewAll?'Show less':'View all','v2-all','link')+'</div></section>'+panel('Share your code','<p class="muted">Guests who prefer to book and pay for their own room can use this code.</p><div class="group-code">GBR-008</div>'+button('Copy booking link','v2-copy','primary wide-btn')+button('Email the code','v2-email-code','wide-btn'))+'</div>',true);
}
function groupCodePage(){return v2Page(v2Title('Book your room','Enter the group code from your organizer to see your group rate.')+panel('Group code','<form id="group-code-form"><label class="field"><span>Group code</span><div class="code-input-row"><input name="code" placeholder="Enter your group code" value="'+(pickup().codeApplied?'GBR-008':'')+'" required>'+button('Apply code','v2-apply')+'</div></label><div id="group-code-error" class="error"></div></form>'+(pickup().codeApplied?'<div class="pickup-callout"><div class="row">'+img('74f1d.svg')+'<b>Code applied · group rates unlocked</b></div><b>'+esc(state.request.group)+'</b><small>'+dates()+' · '+nights()+' nights · Cedar Valley Retreat & Conference Center</small></div>'+button('Continue','v2-choose','primary'):'') ,'','code-card'));}
function roomSummary(payment=false){const type=pickup().selectedType,amount=roomRate(type)*nights();return panel(payment?'Summary':'Your booking',payment?line('Check-in',dateLabel(state.request.start))+line('Check-out',dateLabel(state.request.end))+'<b>Accommodation</b><p class="caption mt">'+esc(type)+' × '+nights()+' nights</p>'+line(money(roomRate(type))+' × '+nights()+' nights',money(amount))+line('Taxes ('+(state.quote.tax?'10':'0')+'%)',money(roomTotal(type)-amount))+line('Total',money(roomTotal(type)),'total')+'<div class="pickup-callout"><b>Group rate applied</b><small>You save $20 per night with code GBR-008</small></div>'+'<div id="individual-payment-summary-error" class="error" role="alert" aria-live="polite"></div>'+button('Pay '+money(roomTotal(type)),'v2-pay','primary wide-btn'):'<div class="detail"><label>Group</label><strong>'+esc(state.request.group)+'</strong></div>'+detail('Room',esc(type))+line(money(roomRate(type))+' × '+nights()+' nights',money(amount))+line('Taxes ('+(state.quote.tax?'10':'0')+'%)',money(roomTotal(type)-amount))+line('Total',money(roomTotal(type)),'total')+button('Continue to payment','v2-checkout','primary wide-btn'));}
function chooseRoomPage(){const p=pickup();return v2Page(v2Title('Choose your room','Your group rate applies to every room in the '+esc(state.request.organization)+' block.')+'<div class="pickup-columns"><div class="stack"><section class="pickup-stay-strip">'+detail('Check-in',dateLabel(state.request.start))+detail('Check-out',dateLabel(state.request.end))+detail('Guests','1 guest')+'</section>'+v2Types.map((type,i)=>{const left=p.invitedSlot?Number(slotById(p.invitedSlot).type===type):openSlots(type).length;return '<section class="pickup-room '+(p.selectedType===type?'selected':'')+'">'+img('6d7d4.png',type,'pickup-room-photo')+'<div class="pickup-room-description"><h3>'+type+'</h3><p>'+['1 single bed · up to 1 guest','1 double bed · up to 2 guests','Cabin with a double bed · up to 4 guests'][i]+'</p><div class="row">'+v2Pill('Group rate')+'<span class="v2-pill open">'+left+' left in your block</span></div></div><div class="pickup-room-rate"><div><del>'+money(roomRate(type)+20).replace('.00','')+'</del> <strong>'+money(roomRate(type)).replace('.00','')+'</strong> <small>/ night</small></div>'+button(p.selectedType===type?'Selected':left?'Select room':'Sold out','v2-select-'+i,p.selectedType===type?'primary':'',!left)+'</div></section>';}).join('')+'</div>'+roomSummary()+'</div>');}
function v2Input(label,name,value='',placeholder='',extra=''){return `<label class="field"><span>${label}</span><input name="${name}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${extra}></label>`;}
function individualPaymentPage(){const d=pickup().guestDraft;return v2Page(v2Title('Your details and payment','Pay for your own room. Your booking is counted in the '+esc(state.request.organization)+' block.')+'<div class="pickup-columns payment"><form id="individual-payment-form" class="stack">'+panel('Guest details','<div class="grid2">'+v2Input('First name','first',d.first,'First name','required maxlength="50"')+v2Input('Last name','last',d.last,'Last name','required maxlength="50"')+v2Input('Email','email',d.email,'you@example.com','type="email" required')+v2Input('Phone *','phone',d.phone,'+1 415 555 0142','type="tel" required')+'</div>')+panel('Payment method',v2Input('Card holder','holder',v2Full(d),'Name on card','required')+'<div class="mt">'+v2Input('Card number','card','','4242 4242 4242 4242','required inputmode="numeric" autocomplete="off"')+'</div><div class="grid2 mt">'+v2Input('Expiry','expiry','','12 / 29','required autocomplete="off"')+v2Input('CVC','cvc','','123','type="password" required maxlength="3" autocomplete="off"')+'</div><p class="hint mt">Demo payment only. Use card 4242 4242 4242 4242; no charge is made.</p><div id="individual-payment-error" class="error"></div>')+'</form>'+roomSummary(true)+'</div>');}
function individualConfirmedPage(){const r=individualById(pickup().lastBooking);if(!r)return groupCodePage();return v2Page('<div class="pickup-confirmation"><span class="pickup-success">'+img('a79b9.svg')+'</span><h1>Your room is booked</h1><p>Reservation #'+r.id+' · A receipt was sent to '+esc(r.guest.email)+'</p></div><div class="pickup-confirmed-columns">'+panel('Stay details','<div class="grid2">'+detail('Guest',esc(v2Full(r.guest)))+detail('Paid',money(r.amount))+detail('Room',esc(r.type))+detail('Group',esc(state.request.organization))+detail('Dates',dates()+' · '+nights()+' nights')+detail('Room number',r.assigned?r.unit:'Assigned at check-in')+'</div>')+panel('What happens next','<div class="next-step"><span class="dot">1</span><p>Your room is counted in the '+esc(state.request.organization)+' block.</p></div><div class="next-step"><span class="dot">2</span><p>The venue assigns your room number before you arrive.</p></div><div class="next-step"><span class="dot">3</span><p>Check in on '+dateLabel(state.request.start)+' from 3:00 PM.</p></div>')+'</div><div class="row mt">'+button('Add to calendar','calendar')+button('View my booking','v2-my-booking','primary')+'</div>');}
function individualListPage(){const rows=pickup().reservations.slice().sort((a,b)=>b.id.localeCompare(a.id)).map(r=>[button('#'+r.id,'v2-record-'+r.id,'link'),esc(v2Full(r.guest)),button('GBR-008','open-block','link'),dateLabel(state.request.start),dateLabel(state.request.end),1,money(r.amount+extrasTotal(r)),money((r.paid?0:r.amount)+extrasTotal(r)-(r.extrasPaid||0)),badge(r.status)]);rows.push([button('#00031','open-reservation','link'),esc(name()),button('GBR-008','open-block','link'),dateLabel(state.request.start),dateLabel(state.request.end),roomSlots().length,money(groupInvoiceTotal()),money(groupInvoiceTotal()-totals().deposit),badge(state.reservation.status)]);return '<div class="admin pickup-pms">'+sfNav()+adminHeader('Reservations','All reservations','',button('New','v2-new'))+'<p class="list-meta">'+rows.length+' items · Sorted by Reservation # · Updated a few seconds ago</p><div class="admin-main"><section class="panel list-table"><div class="list-toolbar">'+'<label class="compact-search"><input name="individual-search" aria-label="Search reservations" placeholder="Search this list…"></label>'+button('List view','v2-list-view')+'</div>'+table(['RESERVATION','CONTACT','GROUP BLOCK','START DATE','END DATE','ROOMS','TOTAL','BALANCE','STATUS'],rows)+'</section></div></div>';}
function currentIndividual(){const r=individualById(pickup().currentId);requireState(r,'Choose an individual reservation.');return r;}
function individualDetailPage(){const r=currentIndividual(),tab=pickup().detailTab||'Details';const info='<section class="reservation-info-card"><h2>Reservation Info</h2><div class="reservation-inner"><div class="reservation-date-row">'+availabilityDateField('Start Date','individual-start',state.request.start)+availabilityDateField('End Date','individual-end',state.request.end)+'</div><div class="reservation-meta">'+detail('Booked by',esc(v2Full(r.guest)))+detail('Taxes enabled',state.quote.tax?'True':'False')+detail('Taxes',money(r.amount-roomRate(r.type)*nights()))+'</div><div class="reservation-card-footer"><div class="row">'+button('Add room','v2-add-service')+button('Add item','v2-add-service')+'</div><div class="reservation-card-total"><span>Grand Total</span><strong>'+money(r.amount)+'</strong></div></div></div></section>';
 const billing='<section class="reservation-info-card"><h2>Billing Info</h2><div class="reservation-inner"><div class="reservation-contact-row">'+v2Input('Contact Name','individual-contact',v2Full(r.guest),'','readonly')+button('Change','v2-contact')+'</div><div class="reservation-meta">'+detail('Email',esc(r.guest.email))+detail('Invoice',button('INV-'+r.id,'v2-invoice','link'))+'</div><div class="reservation-card-footer"><div class="row">'+button('Invoice','v2-invoice')+button('Payments','v2-tab-Payments')+'</div><div class="reservation-card-total"><span>Balance Due</span><strong>'+money(r.paid?0:r.amount)+'</strong></div></div></div></section>';
 const room='<h2 class="reservation-section-title">Reservation Rooms <span>(1/1)</span></h2><div class="reservation-table reservation-rooms-table">'+table(['ROOM','GUEST','START DATE','END DATE','GUESTS','STATUS','LENGTH','ROOM ONLY','TOTAL','ACTIONS'],[['<div class="reservation-room-cell">'+img(r.type==='Standard Single Room'?'91224.png':r.type==='Cabin'?'b6b1d.png':'8c305.png',r.type,'reservation-room-photo')+'<div><small>From Cedar Valley Retreat & Conference Center</small><strong>'+esc(r.type)+'</strong>'+button(r.assigned?'Room '+r.unit:'Assign Room','v2-change-room','link')+'</div></div>',esc(v2Full(r.guest)),dateLabel(state.request.start),dateLabel(state.request.end),'1 / 0',r.status,nights()+' nights',reservationAmount(roomRate(r.type)*nights()),reservationAmount(roomRate(r.type)*nights()),'<button class="room-action" data-action="v2-change-room" aria-label="Room actions">'+img('c0779.svg')+'</button>']])+'</div><div class="reservation-add">'+button('Add','v2-add-service')+'</div>';
 const details=tab==='Details'?room:tab==='Payments'?table(['PAYMENT','METHOD','STATUS','AMOUNT'],[[r.paid?'PAY-'+r.id:'Awaiting payment',r.paid?'Demo card ending 4242':'—',badge(r.paid?'Paid':'Pending'),money(r.paid?r.amount:0)]]):tab==='Files'?'<div class="file-item"><b>Confirmation_'+r.id+'.pdf</b>'+button('Download','v2-download','link')+'</div>':r.activities.map(a=>'<div class="note-item">'+esc(a)+'</div>').join('')||'<p class="muted mt">Reservation created from group block GBR-008.</p>';
 return '<div class="admin reservation-page reservation-v2 pickup-pms">'+sfNav()+'<div class="reservation-page-body"><header class="reservation-record-header"><div>'+breadcrumbs([['Reservations','v2-pms'],['#'+r.id]])+'<div class="row"><span>Reservation</span><h1>#'+r.id+'</h1></div><div class="sub">Group Block &nbsp;'+button('GBR-008','open-block','link')+'</div></div><div class="row">'+button(r.checkedIn?'Checked-In':'Check-In','v2-check-in','',!r.paid||r.checkedIn)+button(r.checkedOut?'Checked-Out':'Check-Out','v2-check-out','',!r.checkedIn||r.checkedOut)+'</div></header><div class="reservation-status-path">'+['Cancelled','Pending Approval','Confirmed'].map(x=>'<div>'+(x===r.status?badge(x):'<strong>'+x+'</strong>')+'</div>').join('')+'</div><div class="reservation-info-cards">'+info+billing+'</div><section class="reservation-details-card"><nav class="tab-bar">'+['Details','Payments','Files','Activities'].map(x=>'<button data-action="v2-tab-'+x+'" class="'+(tab===x?'active':'')+'">'+x+'</button>').join('')+'</nav>'+details+'</section></div></div>';
}
function v2ModalSpec(){const p=pickup();let title='',body='',footer='',guest=state.ui.app==='guest',size='';
 if(modal==='v2-start'){title='Video 2 · Group rooms';body='<p>Continue from your confirmed group, or load the Horizon Foundation story with six guests already assigned.</p>';footer=button('Cancel','close-modal')+(state.reservation?.status==='Confirmed'||state.video2Group?button(state.video2Group?'Resume video 2':'Use current group','v2-current'):'')+button('Load video 2 story','v2-sample','primary');size='small';}
 else if(modal==='v2-add'||modal==='v2-edit'||modal==='v2-staff-new'){const s=p.editSlot?slotById(p.editSlot):null,g=s?.guest||{};title=modal==='v2-staff-new'?'New Reservation':s?.guest?'Change guest assignment':'Add guest';body='<form id="pickup-assign-form"><div class="grid2">'+v2Input('First name','first',g.first,'First name','required')+v2Input('Last name','last',g.last,'Last name','required')+'</div><div class="mt">'+v2Input('Email','email',g.email,'you@example.com','type="email" required')+'</div><div class="grid2 mt"><label class="field"><span>Room</span><select name="slot" required>'+roomSlots().filter(x=>!x.guest||x.id===s?.id).map(x=>'<option value="'+x.id+'" '+(x.id===s?.id?'selected':'')+'>'+esc(x.type)+' · '+x.unit+'</option>').join('')+'</select></label>'+select('Who pays','payer',s?.payer||'Organizer',['Organizer','Guest'])+'</div><div id="pickup-assign-error" class="error"></div></form>';footer=button('Cancel','close-modal')+button('Save assignment','v2-save-guest','primary');size='small';}
 else if(modal==='v2-invites'){const queue=p.inviteQueue.map(slotById).filter(s=>s?.guest);title='Send room invitations';body='<p class="muted mb">Guests who pay for their own room get a link to confirm and pay. Guests you pay for receive a confirmation only.</p>'+queue.map(s=>'<div class="invite-row"><div><b>'+esc(v2Full(s.guest))+'</b><small>'+esc(s.guest.email)+'</small></div>'+v2Pill(s.payer==='Guest'?'Pays own room':'Organizer pays')+'</div>').join('');footer=button('Cancel','close-modal')+button('Send '+queue.length+' invitations','v2-send-invites','primary',!queue.length);size='pickup-invite';}
 else if(modal==='v2-import'){title='Import guest list';body='<p class="muted mb">Paste one guest per line: first name, last name, email, room type, payer.</p><form id="pickup-import-form">'+textarea('Guest list','csv','','required')+'</form><p class="hint mt">Room types: Single, Double, Cabin. Payer: Organizer or Guest.</p><div id="pickup-import-error" class="error"></div>';footer=button('Cancel','close-modal')+button('Import list','v2-import-save','primary');}
 else if(modal==='v2-change-room'){const r=currentIndividual();title='Change room';size='pickup-room-change';body='<b>'+esc(v2Full(r.guest))+' · Reservation #'+r.id+'</b><p class="muted mb">'+dates()+' · '+nights()+' nights · Group Block GBR-008</p><div class="note-box mb">'+detail('Current room',esc(r.type)+' · '+r.unit)+'</div><form id="pickup-change-form"><div class="grid2">'+select('New room type','type',r.type,v2Types)+'<label class="field"><span>New room</span><select name="slot" required>'+roomChangeOptions(r.type,r)+'</select></label></div><p class="mt mb" id="room-change-availability">'+badge('Available')+' Same room type · same group rate, no price change</p><div class="grid2">'+select('Reason','reason','Guest request',['Guest request','Near meeting hall','Accessibility','Maintenance'])+v2Input('Rate','rate','Group rate · '+money(roomRate(r.type))+' per night','','readonly')+'</div><div class="mt">'+textarea('Note','note','Prefers a room close to the meeting hall.')+'</div><div class="mt">'+check('Send an updated confirmation to the guest','notify',true)+'</div><div id="pickup-change-error" class="error"></div></form>';footer=button('Cancel','close-modal')+button('Change room','v2-save-room','primary');}
 else if(modal==='v2-guest-booking'){const r=individualById(p.lastBooking);title='Your reservation #'+r.id;body=detail('Guest',esc(v2Full(r.guest)))+detail('Room',esc(r.type))+detail('Room number',r.assigned?r.unit:'Assigned at check-in')+detail('Dates',dates())+detail('Payment',badge('Paid')+' '+money(r.amount));footer=button('Close','close-modal')+button('Download confirmation','v2-download','primary');size='small';}
 else if(modal==='v2-invoice'){const r=currentIndividual();title='Invoice INV-'+r.id;body=detail('Billed to',esc(v2Full(r.guest)))+detail('Group','GBR-008')+line(esc(r.type)+' × '+nights()+' nights',money(roomRate(r.type)*nights()))+line('Tax',money(r.amount-roomRate(r.type)*nights()))+guestExtras(r).map(x=>line(x.title+' (incl. tax)',money(x.price*1.1))).join('')+line('Total',money(r.amount+extrasTotal(r)),'total')+line('Paid',money((r.paid?r.amount:0)+(r.extrasPaid||0)))+line('Balance due',money((r.paid?0:r.amount)+extrasTotal(r)-(r.extrasPaid||0)));footer=button('Close','close-modal')+button('Download','v2-download','primary');}
 else if(modal==='v2-services'){title='Reservation services';body='<p>This reservation contains one room within GBR-008. Use Change room to choose another available room, or create another guest booking with the group code.</p>';footer=button('Close','close-modal')+button('Change room','v2-change-room','primary');size='small';}
 else if(modal==='v2-email-code'){title='Share group code';body='<form id="pickup-share-form">'+v2Input('Recipient email','email','','guest@example.com','type="email" required')+'</form><div class="group-code">GBR-008</div><p class="muted">An invitation will appear in the demo guest inbox.</p>';footer=button('Cancel','close-modal')+button('Send invitation','v2-send-code','primary');size='small';}
 else if(modal==='v2-contact'){const r=currentIndividual();title='Guest contact';body=detail('Name',esc(v2Full(r.guest)))+detail('Email',esc(r.guest.email))+detail('Phone',esc(r.guest.phone||'—'));footer=button('Close','close-modal');size='small';}
 else return null;
 return {title,body,footer,guest,size};
}
