adminReservation=function(){let html=v2Base.reservation();if(!v2Active())return html;const t=totals(),credit=pickupCredit();html=html.replaceAll(money(t.total),money(groupInvoiceTotal())).replaceAll(money(t.total-(state.quote.payment?.amount||t.deposit)),money(groupInvoiceTotal()-(state.quote.payment?.amount||t.deposit)));return html.replace('<div class="reservation-info-cards">','<p class="pickup-billing-note">Original group booking '+money(t.total)+' · Individual room payments credited '+money(credit)+' · Organizer invoice '+money(groupInvoiceTotal())+'</p><div class="reservation-info-cards">');};
adminInvoice=function(){const html=v2InvoiceBase();if(!v2Active())return html;const t=totals();return html.replaceAll(money(t.total),money(groupInvoiceTotal())).replaceAll(money(t.total-t.deposit),money(groupInvoiceTotal()-t.deposit)).replace('<div class="summary-line total">',line('Individual room credits','−'+money(pickupCredit()))+'<div class="summary-line total">').replace('Demo payment received Sep 22, 2026. No real charge was made.','Individual room payments credited: '+money(pickupCredit())+'. The signed quote remains '+money(t.total)+'. Demo only; no charge was made.');};
