function downloadIndividualPDF(r){const lines=['CEDAR VALLEY RETREAT & CONFERENCE CENTER','Reservation #'+r.id,'Group block GBR-008',v2Full(r.guest),r.guest.email,r.type+' - '+(r.assigned?r.unit:'Assigned at check-in'),dates()+' - '+nights()+' nights','Accommodation: '+money(roomRate(r.type)*nights()),'Tax: '+money(r.amount-roomRate(r.type)*nights()),...guestExtras(r).map(x=>x.title+': '+money(x.price*1.1)+' incl. tax'),'Total: '+money(r.amount+extrasTotal(r)),'Paid: '+money((r.paid?r.amount:0)+(r.extrasPaid||0)),'Balance: '+money((r.paid?0:r.amount)+extrasTotal(r)-(r.extrasPaid||0)),'Demo reservation - no real charge.'];const safe=s=>s.replace(/[^\x20-\x7e]/g,'-').replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)');const stream='BT /F1 11 Tf 18 TL 45 790 Td '+lines.map((s,i)=>(i?'T* ':'')+'('+safe(s)+') Tj').join('\n')+' ET';const objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>','<< /Length '+stream.length+' >>\nstream\n'+stream+'\nendstream'];let pdf='%PDF-1.4\n',offsets=[];objects.forEach((o,i)=>{offsets.push(pdf.length);pdf+=(i+1)+' 0 obj\n'+o+'\nendobj\n';});const x=pdf.length;pdf+='xref\n0 6\n0000000000 65535 f \n'+offsets.map(n=>String(n).padStart(10,'0')+' 00000 n \n').join('')+'trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n'+x+'\n%%EOF';downloadBlob(pdf,'application/pdf','Confirmation_'+r.id+'.pdf');}
renderOverlay=function(){const spec=modal?.startsWith('v2-')?v2ModalSpec():null;if(!spec)return v2Base.overlay();const {title,body,footer,guest,size}=spec;$('#overlay').innerHTML='<div class="modal-backdrop"><section class="modal '+size+' '+(guest?'guest-modal pickup-modal':'')+'" role="dialog" aria-modal="true" aria-label="'+esc(title)+'"><button class="modal-close" data-action="close-modal" aria-label="Close dialog">×</button><header class="modal-header">'+title+'</header><div class="modal-content">'+body+'</div><footer class="modal-footer">'+footer+'</footer></section></div>';document.body.style.overflow='hidden';$('#overlay .modal-close')?.focus({preventScroll:true});};
demoBar=function(){let html=v2Base.bar();html=html.replace('<div class="demo-tools">','<div class="demo-tools"><button data-action="v2-video1" '+(!v2Active()?'class="video-active"':'')+'>Video 1</button><button data-action="v2-start" '+(v2Active()?'class="video-active"':'')+'>Video 2</button>');if(v2Active()){const tabs=state.ui.app==='guest'?[['Organizer','v2-organizer'],['Book with group code','v2-code'],['Guest inbox','v2-inbox']]:[['Reservations','v2-pms'],['Group reservation','open-reservation'],['Availability','availability']];html=html.replace(/<div class="demo-progress">[\s\S]*?<\/div><span>[\s\S]*?<\/span><\/div>/,'');html+='<nav class="pickup-demo-nav" aria-label="Video 2 demo views"><span>VIDEO 2</span>'+tabs.map(([t,a])=>button(t,a,'link')).join('')+'</nav>';}return html;};
