availabilityBookings=function(row){if(!v2Active())return v2Base.bookings(row);const b=v2Base.bookings(row).filter(x=>!x.demo);const s=roomSlots().find(s=>s.unit===row.unit&&s.type===row.type);if(s){const r=slotReservation(s);b.push({label:s.guest?v2Full(s.guest):'Held for '+state.request.organization,start:state.request.start,end:state.request.end,status:s.guest&&(s.payer==='Organizer'||r?.paid)?'Confirmed':'Pending Approval',demo:true});}else if(row.type==='Meeting Hall'&&row.index===1)b.push({label:state.request.organization,start:state.request.start,end:availabilityDate(state.request.start,state.quote.spaceDays),status:'Confirmed',demo:true});return b;};
reservationRooms=function(){if(!v2Active())return v2Base.rooms();const slots=state.ui.allRooms?roomSlots():roomSlots().slice(0,7);return '<div class="reservation-table reservation-rooms-table">'+table(['ROOM','GUEST','START DATE','END DATE','GUESTS','STATUS','LENGTH','ROOM ONLY','TOTAL','ACTIONS'],slots.map(s=>['<div class="reservation-room-cell">'+img(s.type==='Standard Single Room'?'91224.png':s.type==='Cabin'?'b6b1d.png':'8c305.png',s.type,'reservation-room-photo')+'<div><small>From Cedar Valley Retreat & Conference Center</small><strong>'+s.type+'</strong>'+button('Room '+s.unit,'v2-slot-'+s.id,'link')+'</div></div>',s.guest?esc(v2Full(s.guest)):'Not assigned',dateLabel(state.request.start),dateLabel(state.request.end),s.guest?'1 / 0':'0 / 0',s.guest?s.status:'Held for group',nights()+' nights',reservationAmount(roomRate(s.type)*nights()),reservationAmount(roomRate(s.type)*nights()),button('Manage','v2-slot-'+s.id,'link')]))+'<div class="table-hint">Showing '+slots.length+' of '+roomSlots().length+' rooms · '+button(state.ui.allRooms?'Show less':'View all','all-rooms','link')+'</div></div>';};
function guestInboxPage(){const pending=pickup().reservations.filter(r=>!r.paid);return v2Page(v2Title('Your invitations','Room invitations for '+esc(state.request.group))+'<div class="stack">'+pending.map(r=>panel('Room invitation · '+esc(v2Full(r.guest)),'<p class="muted">'+esc(r.guest.email)+'</p><div class="mt">'+detail('Room',esc(r.type))+detail('Group code','GBR-008')+detail('Amount due',money(r.amount))+button('Confirm and pay','v2-invitation-'+r.id,'primary')+'</div>')).join('')+(pickup().sharedEmail?panel('Group code invitation','<p>Sent to '+esc(pickup().sharedEmail)+'</p><div class="group-code">GBR-008</div>'+button('Book your room','v2-code','primary')):'')+(!pending.length&&!pickup().sharedEmail?'<p class="muted">No invitations waiting.</p>':'')+'</div>');}
function saveGuestAssignment(values,oldId){const old=oldId?slotById(oldId):null,s=slotById(values.slot);requireState(s&&(!s.guest||s.id===oldId),'That room is already assigned.');requireState(values.first.trim()&&values.last.trim()&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email),'Enter a name and valid email.');requireState(!roomSlots().some(x=>x.id!==oldId&&x.guest?.email.toLowerCase()===values.email.trim().toLowerCase()),'This guest is already assigned.');const prev=old&&slotReservation(old);requireState(!prev?.paid,'Manage a paid guest through their individual reservation.');if(old&&old.id!==s.id){old.guest=null;old.payer=null;old.status='Open';}s.guest={first:values.first.trim(),last:values.last.trim(),email:values.email.trim(),phone:''};s.payer=values.payer;s.status=values.payer==='Organizer'?'Assigned':'Invited';if(prev){pickup().reservations=pickup().reservations.filter(r=>r.id!==prev.id);}if(values.payer==='Guest')pickup().reservations.push({id:prev?.id||String(pickup().nextId++).padStart(5,'0'),slotId:s.id,guest:{...s.guest},type:s.type,unit:s.unit,status:'Pending Approval',paid:false,amount:roomTotal(s.type),activities:['Guest assigned by organizer.']});pickup().inviteQueue=[...new Set([...pickup().inviteQueue.filter(id=>id!==oldId),s.id])];return s;}
function payIndividual(values){const p=pickup();requireState(values.first.trim()&&values.last.trim()&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email),'Complete the guest details.');requireState(values.card.replace(/\D/g,'')==='4242424242424242','Use demo card 4242 4242 4242 4242.');requireState(/^(0[1-9]|1[0-2])\s*\/\s*\d{2}$/.test(values.expiry.trim())&&/^\d{3}$/.test(values.cvc.trim()),'Enter expiry MM / YY and a 3-digit demo CVC.');const invited=p.invitedSlot?slotById(p.invitedSlot):null;requireState(!invited||invited.guest.email.toLowerCase()===values.email.trim().toLowerCase(),'Use the invited guest email.');requireState(!roomSlots().some(s=>s.id!==invited?.id&&s.guest?.email.toLowerCase()===values.email.trim().toLowerCase()),'This guest already has a room in the block.');const slot=invited||openSlots(p.selectedType)[0];requireState(slot&&(!slot.guest||invited),'This room is no longer available. Choose another room.');let r=slotReservation(slot);requireState(!r?.paid,'This reservation is already paid.');const g={first:values.first.trim(),last:values.last.trim(),email:values.email.trim(),phone:values.phone.trim()};if(!r){const id=p.reservations.some(r=>r.id==='00032')?String(p.nextId++).padStart(5,'0'):'00032';r={id,slotId:slot.id,activities:[]};p.reservations.push(r);}Object.assign(r,{guest:g,type:slot.type,unit:slot.unit,status:'Confirmed',paid:true,amount:roomTotal(slot.type),payment:{last4:'4242',reference:'PAY-'+r.id,amount:roomTotal(slot.type)},assigned:true});r.activities.push('Individual room booked and demo payment received.');Object.assign(slot,{guest:g,payer:'Guest',status:'Paid'});p.lastBooking=r.id;p.currentId=r.id;p.invitedSlot=null;p.guestDraft=g;state.ui.guest='individual-confirmed';state.ui.admin='individual-list';p.inviteQueue=p.inviteQueue.filter(id=>id!==slot.id);save();render();window.scrollTo(0,0);return r;}
function changeIndividualRoom(values){const r=currentIndividual(),old=slotById(r.slotId),next=slotById(values.slot);requireState(next&&next.id!==old.id&&!next.guest&&next.type===values.type,'Choose an available room.');requireState(roomTotal(next.type)===r.amount,'Choose a room at the same rate. Rate-changing upgrades need a new payment quote.');Object.assign(next,{guest:old.guest,payer:old.payer,status:old.status});Object.assign(old,{guest:null,payer:null,status:'Open'});Object.assign(r,{slotId:next.id,type:next.type,unit:next.unit,assigned:true});r.activities.push('Room changed from '+old.unit+' to '+next.unit+' · '+values.reason+'. '+values.note+(values.notify?' Updated confirmation sent.':''));pickup().activities.push(v2Full(r.guest)+' moved from '+old.unit+' to '+next.unit+'.');return r;}
